import{_ as a,o as n,c as e,a3 as o}from"./chunks/framework.BzWmN0d8.js";const g=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":1788354533000}'),i={name:"zh/guide/architecture.md"};function l(p,s,t,c,d,r){return n(),e("div",null,[...s[0]||(s[0]=[o(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p><code>lograil</code> 采用分层设计，让每个关注点彼此隔离、便于测试。一次日志调用会按可预测的顺序流经这些层。</p><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to &quot;分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  log.info(message, ...args)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │   Logger      │  构建结构化的 LogEntry（时间戳、作用域、</span></span>
<span class="line"><span>   │  （门面）      │  上下文、元数据、error、级别）</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │   Pipeline     │  1. 过滤器  —— 丢弃条目（如按级别/作用域）</span></span>
<span class="line"><span>   │                │  2. 处理器  —— 转换/增强/脱敏/序列化</span></span>
<span class="line"><span>   │                │  3. 格式化器 —— 序列化为字符串/JSON</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │  Plugins      │  异步拦截每条条目（可丢弃/修改），</span></span>
<span class="line"><span>   │               │  并可在运行时添加传输器 / 重构管道</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>   ┌───────────────┘</span></span>
<span class="line"><span>   │  Transports   │  最终落点：控制台、滚动文件、IPC、OTLP、自定义</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span>          ▲</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>   ┌───────────────┐</span></span>
<span class="line"><span>   │  Runtime       │  隔离环境差异（时钟、pid、文件系统、默认值）</span></span>
<span class="line"><span>   │  Adapter       │  —— 自动探测，或显式传入</span></span>
<span class="line"><span>   └───────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Context  —— 附加到每条日志中的持久化结构化字段（另含可选的</span></span>
<span class="line"><span>              环境异步上下文）。</span></span></code></pre></div><ul><li><strong>Logger</strong>：把调用转换为 <code>LogEntry</code>。第一个参数可以是 <code>string</code>、<code>Error</code> 或任意值（对象会被保留为结构化数据）。条目携带 <code>context</code>（持久化、可继承的请求级数据）和 <code>metadata</code>（单条条目级，通常由处理器注入——详见 <a href="./context">上下文与元数据</a> 了解区别）。</li><li><strong>Pipeline</strong>：先运行 <code>Filter</code>（返回 <code>false</code> 即丢弃），再依次运行 <code>Processor</code>（增强/脱敏/序列化……），最后由 <code>Formatter</code> 生成线上形态。内置处理器 <code>createRedactProcessor</code>、<code>createSerializeProcessor</code> 即插于此。</li><li><strong>Plugins</strong>：在管道之后通过每条条目的异步 <code>intercept</code> 钩子运行。可丢弃条目（返回 <code>null</code>）或改写，并通过 <code>PluginContext</code> 在运行时重新配置 logger。</li><li><strong>Transports</strong>：最终落点（控制台、<code>rotating file</code>、IPC、<code>OTLP</code> 或自定义）。<code>write</code> 可以是异步的；若是异步，logger 会在 <code>flush()</code> / <code>destroy()</code> 时等待其完成。每个传输器还可声明自己的 <code>level</code> 做独立过滤。</li><li><strong>Runtime Adapter</strong>：抽象环境差异（Web / Node / Electron），因此同一套 logger 代码处处可用。</li><li><strong>Context</strong>：合并进每条日志的 <code>context</code> 字段；作用域 logger 会获得隔离的子上下文。此外还有<strong>环境（异步）上下文</strong>——基于 <code>AsyncLocalStorage</code> 的请求级字段，在 <code>await</code> 之间自动继承，会被叠加在 logger 上下文之上（浏览器中为无操作）。</li></ul><h2 id="异步与生命周期" tabindex="-1">异步与生命周期 <a class="header-anchor" href="#异步与生命周期" aria-label="Permalink to &quot;异步与生命周期&quot;">​</a></h2><p>从调用方视角看，日志记录是同步的，但写入会经由内部队列排空，因此异步传输器与插件拦截都不会阻塞你的代码：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;done&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 立即返回</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flush</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 等待队列（含异步写入）清空</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">destroy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 先 flush，再释放插件、关闭传输器</span></span></code></pre></div><p>由于插件的 <code>onEntry</code> 钩子会被 <code>await</code> 并链式执行，且异步传输写入会进入队列，因此在进程退出前调用 <code>flush()</code>（或 <code>destroy()</code>）能保证缓冲区中的日志不丢失。Logger 通过运行时的 <code>lifecycle</code> 钩子来接线 flush / 崩溃行为：所以 <code>autoFlushOnExit</code>（或 <code>attachExitHandlers</code>）会在宿主退出时 flush——Node 的 <code>beforeExit</code> / <code>SIGINT</code> / <code>SIGTERM</code>、Electron <strong>主进程</strong>的 <code>app</code> <code>before-quit</code> / <code>will-quit</code>、Web 的 <code>pagehide</code> / <code>visibilitychange</code>；<code>watchUncaughtErrors</code> 会把未捕获异常 / 未处理的拒绝以 <code>fatal</code> 记录后再退出；<code>redirectConsole</code> 把 <code>console.*</code> 桥接进 logger。</p><h2 id="过滤发生在哪里" tabindex="-1">过滤发生在哪里 <a class="header-anchor" href="#过滤发生在哪里" aria-label="Permalink to &quot;过滤发生在哪里&quot;">​</a></h2><p>有三道相互独立的闸门：</p><ol><li><strong>logger 级别闸门</strong>：<code>setLevel</code> 在条目进入管道前丢弃低于阈值的条目，因此被廉价丢弃的条目不会消耗处理成本。</li><li><strong>管道过滤器</strong>：任意谓词（<code>createLevelFilter</code>、<code>createScopeFilter</code>、<code>createSampler</code>、<code>combineFilters</code>、自定义）在管道内运行。</li><li><strong>按传输器级别</strong>：每个传输器可声明自己的 <code>level</code>；低于它的条目仅被该传输器跳过，从而让一个 logger 分流（例如 <code>error</code> 及以上发往远端，其余写入文件）。</li></ol><h2 id="为何如此分层" tabindex="-1">为何如此分层 <a class="header-anchor" href="#为何如此分层" aria-label="Permalink to &quot;为何如此分层&quot;">​</a></h2><ul><li><strong>关注点分离</strong>：格式化与目标解耦——同一条目可以用不同格式同时进入控制台和文件。</li><li><strong>可组合</strong>：过滤器/处理器/传输器都是普通函数或对象，易于单元测试与复用。</li><li><strong>可扩展</strong>：插件可在运行时重构管道、添加落点，而无需改动业务代码。</li><li><strong>可移植</strong>：运行时适配器使同一套 API 在 Web、Node 与 Electron 上通用，包括 Electron 中渲染进程→主进程的日志汇聚。</li></ul>`,14)])])}const k=a(i,[["render",l]]);export{g as __pageData,k as default};
